-- Patient self-service read access is limited to patient-linked orders, lab bookings and released results.
drop policy if exists customer_orders_read on public.pharmacy_customer_orders;
create policy customer_orders_read on public.pharmacy_customer_orders for select to authenticated using(private.has_module_access(tenant_id,'pharmacy_suite',branch_id,false) or exists(select 1 from public.patients p where p.id=pharmacy_customer_orders.patient_id and p.tenant_id=pharmacy_customer_orders.tenant_id and (p.created_by=auth.uid() or exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=lower(p.email)))));
drop policy if exists customer_order_items_read on public.pharmacy_customer_order_items;
create policy customer_order_items_read on public.pharmacy_customer_order_items for select to authenticated using(exists(select 1 from public.pharmacy_customer_orders o where o.id=pharmacy_customer_order_items.order_id and o.tenant_id=pharmacy_customer_order_items.tenant_id and (private.has_module_access(o.tenant_id,'pharmacy_suite',o.branch_id,false) or exists(select 1 from public.patients p where p.id=o.patient_id and p.tenant_id=o.tenant_id and (p.created_by=auth.uid() or exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=lower(p.email)))))));
create policy pharmacy_sales_patient_read on public.pharmacy_sales for select to authenticated using(private.has_module_access(tenant_id,'pharmacy_suite',branch_id,false) or exists(select 1 from public.patients p where p.id=pharmacy_sales.patient_id and p.tenant_id=pharmacy_sales.tenant_id and (p.created_by=auth.uid() or exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=lower(p.email)))));
drop policy if exists patient_lab_booking_read on public.lab_bookings;
create policy patient_lab_booking_read on public.lab_bookings for select to authenticated using(private.has_module_access(tenant_id,'laboratory_suite',branch_id,false) or exists(select 1 from public.patients p where p.id=lab_bookings.patient_id and p.tenant_id=lab_bookings.tenant_id and (p.created_by=auth.uid() or exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=lower(p.email)))));
create policy patient_lab_booking_items_read on public.lab_booking_items for select to authenticated using(exists(select 1 from public.lab_bookings b where b.id=lab_booking_items.booking_id and b.tenant_id=lab_booking_items.tenant_id and (private.has_module_access(b.tenant_id,'laboratory_suite',b.branch_id,false) or exists(select 1 from public.patients p where p.id=b.patient_id and p.tenant_id=b.tenant_id and (p.created_by=auth.uid() or exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=lower(p.email)))))));
drop policy if exists lab_samples_branch_read on public.lab_samples;
create policy lab_samples_patient_read on public.lab_samples for select to authenticated using(exists(select 1 from public.lab_booking_items li join public.lab_bookings b on b.id=li.booking_id and b.tenant_id=li.tenant_id where li.id=lab_samples.booking_item_id and li.tenant_id=lab_samples.tenant_id and (private.has_module_access(b.tenant_id,'laboratory_suite',b.branch_id,false) or exists(select 1 from public.patients p where p.id=b.patient_id and p.tenant_id=b.tenant_id and (p.created_by=auth.uid() or exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=lower(p.email)))))));
drop policy if exists lab_results_branch_read on public.lab_results;
create policy lab_results_patient_released_read on public.lab_results for select to authenticated using((result_status='released' and exists(select 1 from public.lab_booking_items li join public.lab_bookings b on b.id=li.booking_id and b.tenant_id=li.tenant_id join public.patients p on p.id=b.patient_id and p.tenant_id=b.tenant_id where li.id=lab_results.booking_item_id and li.tenant_id=lab_results.tenant_id and (p.created_by=auth.uid() or exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=lower(p.email))))) or private.has_module_access(tenant_id,'laboratory_suite',null,false));
